window.__finlexDocLoaded(10002,{"id":10002,"articles":[{"id":1000002,"no":"Decision Summary","heading":"Forward-Looking Macroeconomic Scenarios in ECL (IFRS 9.5.5.17(c))","text":"[Issue & Enforcement Decision]\n• An issuer estimated expected credit losses relying solely on historical loss rates without incorporating forward-looking macroeconomic factors.\n• The enforcer required the issuer to collect current and projected macroeconomic data and incorporate it as actual input data into the ECL estimation using more than one economic scenario.\n\n[Regulatory Rationale]\n• Under IFRS 9.5.5.17(c), ECL must reflect reasonable and supportable information available without undue cost or effort at the reporting date about past events, current conditions, and forecasts of future economic conditions, evaluated across an unbiased probability-weighted range of outcomes.\n\nSource (ESMA 29th Extract): https://www.esma.europa.eu/sites/default/files/2024-05/ESMA32-193237008-8267_29th_Extract_from_the_EECS_s_Database_of_Enforcement.pdf","seq":0}]});
